package org.slavicmyths.volkolak;
import net.neoforged.bus.api.*;
import net.neoforged.neoforge.event.entity.living.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import org.slavicmyths.registry.ModItems;
import org.slavicmyths.military.*;
@net.neoforged.fml.common.EventBusSubscriber(modid="slavicmyths")
public final class VolkolakEvents {
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void lethal(LivingDamageEvent.Pre e){if(!(e.getEntity() instanceof CursedVolkolak boss)||!(boss.level() instanceof ServerLevel w)||boss.encounter==null)return;var r=VolkolakRecords.get(w).encounters.get(boss.encounter);if(r==null||!boss.getUUID().equals(r.boss))return;if(boss.move()==CursedVolkolak.Move.ESCAPE){e.setNewDamage(0);return;}if(e.getNewDamage()>0&&e.getNewDamage()>=boss.getHealth()){e.setNewDamage(Math.max(0,boss.getHealth()-1));VolkolakStory.lethal(boss);}}
 @SubscribeEvent public static void damaged(LivingDamageEvent.Post e){if(!(e.getEntity() instanceof CursedVolkolak boss)||!(boss.level() instanceof ServerLevel w)||e.getNewDamage()<=0||boss.encounter==null)return;var p=GreyWolfStoryEvents.owner(e.getSource(),w);var data=VolkolakRecords.get(w);var record=data.encounters.get(boss.encounter);if(p!=null&&record!=null&&boss.getUUID().equals(record.boss)&&p.distanceToSqr(boss)<=48*48){record.participants.put(p.getUUID(),w.getGameTime());data.setDirty();}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e){if(e.getEntity() instanceof ServerPlayer p&&p.tickCount%40==0&&GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.ACTIVE){VolkolakStory.ensure(p,net.minecraft.core.BlockPos.of(GreyWolfStory.data(p).getLong("WolfHome")));org.slavicmyths.wolf.WolfStoryNetwork.changed(p);}}
 @SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent e){clear(e.getEntity());}
 @SubscribeEvent public static void login(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){clear(e.getEntity());}
 @SubscribeEvent public static void dimension(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerChangedDimensionEvent e){clear(e.getEntity());}
 @SubscribeEvent public static void death(LivingDeathEvent e){if(e.getEntity() instanceof net.minecraft.world.entity.player.Player p)clear(p);if(e.getEntity() instanceof CursedVolkolak boss&&boss.encounter!=null&&boss.level() instanceof ServerLevel w){var record=VolkolakRecords.get(w).encounters.get(boss.encounter);if(record!=null&&boss.getUUID().equals(record.boss)){VolkolakStory.lethal(boss);e.setCanceled(true);}}}
 private static void clear(net.minecraft.world.entity.player.Player p){if(p.getVehicle() instanceof CursedVolkolak)p.stopRiding();p.getPersistentData().remove("VolkolakHolder");p.getPersistentData().remove("VolkolakHeldUntil");}
 /** Destruction/expiration is proof of loss. Merely putting the skull in an unloaded chest is not. */
 public static void lost(ItemEntity item){if(!(item.level() instanceof ServerLevel w)||!item.getItem().is(ModItems.CURSED_VOLKOLAK_SKULL.get()))return;var n=item.getItem().getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(!n.hasUUID("Owner")||!n.hasUUID("Encounter")||!n.hasUUID("Nonce"))return;var data=VolkolakRecords.get(w.getServer().overworld());var e=data.encounters.get(n.getUUID("Encounter"));if(e!=null&&n.getUUID("Nonce").equals(e.issues.get(n.getUUID("Owner")))&&!e.returned.contains(n.getUUID("Owner"))){e.issues.remove(n.getUUID("Owner"));data.setDirty();}}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void expired(net.neoforged.neoforge.event.entity.item.ItemExpireEvent e){if(e.getEntity().level() instanceof ServerLevel w){var item=e.getEntity();w.getServer().tell(new net.minecraft.server.TickTask(w.getServer().getTickCount()+1,()->{if(item.isRemoved()&&(item.getRemovalReason()==net.minecraft.world.entity.Entity.RemovalReason.DISCARDED||item.getRemovalReason()==net.minecraft.world.entity.Entity.RemovalReason.KILLED))lost(item);}));}}
 @SubscribeEvent public static void removed(net.neoforged.neoforge.event.entity.EntityLeaveLevelEvent e){if(e.getEntity() instanceof ItemEntity item&&item.getRemovalReason()==net.minecraft.world.entity.Entity.RemovalReason.KILLED)lost(item);if(e.getEntity() instanceof CursedVolkolak boss&&boss.level() instanceof ServerLevel w&&boss.encounter!=null&&boss.getRemovalReason()==net.minecraft.world.entity.Entity.RemovalReason.DISCARDED){var data=VolkolakRecords.get(w);var record=data.encounters.get(boss.encounter);if(record!=null&&boss.getUUID().equals(record.boss)&&record.stage.equals("FIGHT")){record.boss=null;record.stage="PENDING";data.setDirty();}}}

 @SubscribeEvent public static void placed(net.neoforged.neoforge.event.level.BlockEvent.EntityPlaceEvent e){if(e.getLevel() instanceof ServerLevel w&&e.getEntity() instanceof net.minecraft.world.entity.player.Player&&w.dimension()==net.minecraft.world.level.Level.OVERWORLD){var d=VolkolakRecords.get(w);if(d.editedChunks.add(net.minecraft.world.level.ChunkPos.asLong(e.getPos().getX()>>4,e.getPos().getZ()>>4)))d.setDirty();}}
 @SubscribeEvent public static void pickup(net.neoforged.neoforge.event.entity.player.ItemEntityPickupEvent.Pre e){var item=e.getItemEntity().getItem();if(!item.is(ModItems.CURSED_VOLKOLAK_SKULL.get()))return;var tag=item.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(tag.hasUUID("Owner")&&!tag.getUUID("Owner").equals(e.getPlayer().getUUID()))e.setCanPickup(net.neoforged.neoforge.common.util.TriState.FALSE);}
 private VolkolakEvents(){}
}
